<?php
namespace App\Http\Controllers;
use App\Services\{Tenant,StaffAccess,SalonStore,ProviderReminders,ClientInvitations,Clients,SystemIssues};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Carbon\CarbonImmutable as Date;
final class ProviderToolsController {
 private function provider(Request $r):int{abort_unless($r->session()->get('admin')===true&&(int)$r->session()->get('provider_id',1)===app(Tenant::class)->id,403);return app(Tenant::class)->id;}
 public function reminders(Request $r,?string $id=null){
  $provider=$this->provider($r);$enabled=app(SalonStore::class)->read()['settings']['providerRemindersEnabled']??true;if(!$enabled&&$r->isMethod('GET'))return response()->json(['reminders'=>[],'occurrences'=>[]]);abort_unless($enabled,422,'A saját emlékeztetők használata ki van kapcsolva.');$q=DB::table('provider_reminders')->where('provider_id',$provider);if(StaffAccess::editor($r))$q->where('staff_id',$r->attributes->get('provider_member')->staff_id);
  if($r->isMethod('GET')){$v=$r->validate(['from'=>'required|date_format:Y-m-d','to'=>'required|date_format:Y-m-d|after_or_equal:from']);abort_if(Date::parse($v['from'])->diffInDays(Date::parse($v['to']))>62,422,'Legfeljebb 62 nap kérhető le.');$rows=$q->get();return response()->json(['reminders'=>$rows,'occurrences'=>$rows->flatMap(fn($row)=>ProviderReminders::occurrences($row,$v['from'],$v['to']))->values()]);}
  $row=$id?(clone $q)->where('id',$id)->first():null;if($id)abort_unless($row,404);
  if($r->isMethod('DELETE')){DB::transaction(function()use($row,$q){DB::table('reminder_completions')->where('reminder_id',$row->id)->delete();$q->where('id',$row->id)->delete();});return response()->json(['ok'=>true]);}
  if($r->isMethod('PATCH')){$v=$r->validate(['date'=>'required|date_format:Y-m-d','completed'=>'required|boolean']);abort_unless(ProviderReminders::occurrences($row,$v['date'],$v['date']),422);if($v['completed'])DB::table('reminder_completions')->updateOrInsert(['reminder_id'=>$id,'occurrence_date'=>$v['date']],['completed_at'=>now()]);else DB::table('reminder_completions')->where('reminder_id',$id)->where('occurrence_date',$v['date'])->delete();return response()->json(['ok'=>true]);}
  $v=$r->validate(['title'=>'required|string|max:150','notes'=>'nullable|string|max:3000','staffId'=>'required|string|max:80','startsAt'=>'required|date_format:Y-m-d\TH:i','duration'=>'required|integer|min:5|max:1440','frequency'=>'required|in:none,daily,weekly,monthly','untilDate'=>'nullable|date_format:Y-m-d','count'=>'nullable|integer|min:0|max:10000']);$staff=collect(app(SalonStore::class)->read()['staff'])->first(fn($p)=>$p['id']===$v['staffId']&&empty($p['archived']));abort_unless($staff,422,'Válassz aktív munkatársat.');if(StaffAccess::editor($r))abort_unless($v['staffId']===$r->attributes->get('provider_member')->staff_id,403);abort_if(!empty($v['untilDate'])&&$v['untilDate']<substr($v['startsAt'],0,10),422,'A végdátum nem előzheti meg a kezdést.');
  $id??=(string)Str::uuid();$values=['staff_id'=>$v['staffId'],'title'=>trim($v['title']),'notes'=>$v['notes']??'','starts_at'=>str_replace('T',' ',$v['startsAt']).':00','duration'=>$v['duration'],'frequency'=>$v['frequency'],'until_date'=>$v['untilDate']??null,'occurrence_count'=>$v['count']??0,'updated_at'=>now()];if($row)$q->where('id',$id)->update($values);else{abort_if(DB::table('provider_reminders')->where('provider_id',$provider)->count()>=500,422,'Legfeljebb 500 emlékeztetősorozat kezelhető.');DB::table('provider_reminders')->insert($values+['id'=>$id,'provider_id'=>$provider,'created_at'=>now()]);}return response()->json(['id'=>$id]);
 }
 public function invite(Request $r,string $id){$this->provider($r);abort_if(StaffAccess::editor($r),403);$v=$r->validate(['channel'=>'required|in:email,sms','acceptSmsFee'=>'exclude_unless:channel,sms|required|accepted']);$state=app(SalonStore::class)->read();$client=collect($state['clients'])->first(fn($c)=>$c['id']===$id&&Clients::visible($c));abort_unless($client,404);return response()->json(ClientInvitations::manual($state,$client,$v['channel']));}
 public function issues(Request $r){abort_unless($r->session()->get('platform_admin')===true,403);if($r->isMethod('PATCH')){$v=$r->validate(['id'=>'required|integer','resolved'=>'required|boolean']);DB::table('system_issues')->where('id',$v['id'])->update(['resolved'=>$v['resolved']]);return response()->json(['ok'=>true]);}$v=$r->validate(['category'=>'nullable|string|max:40']);$rows=DB::table('system_issues')->when($v['category']??null,fn($q,$c)=>$q->where('category',$c))->orderBy('resolved')->orderByDesc('last_seen_at')->limit(200)->get();return response()->json(['issues'=>$rows,'retentionDays'=>30]);}
 public function clientIssue(Request $r){$p=$this->provider($r);$v=$r->validate(['code'=>'required|in:script_error,promise_rejection']);SystemIssues::record('browser',$v['code'],'A szolgáltatói felületen böngészőhiba történt.',$p);return response()->json(['ok'=>true]);}
}
